    target = [-1] * 26
    inS = [False] * 26

    for i in range(N):
        a = ord(S[i]) - 97
        b = ord(T[i]) - 97
        if target[a] == -1:
            target[a] = b
        elif target[a] != b:
            print(-1)
            return
        inS[a] = True

    # letters that never appear in S stay unchanged
    for i in range(26):
        if target[i] == -1:
            target[i] = i

    # ---------- DSU for the 26 letters ----------
    parent = list(range(26))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx = find(x)
        ry = find(y)
        if rx != ry:
            parent[ry] = rx

    for i in range(26):
        union(i, target[i])

    # group vertices by component
    comp = {}
    for i in range(26):
        r = find(i)
        comp.setdefault(r, []).append(i)

    ans = 0
    for verts in comp.values():
