            if inS[v]:
                cntS += 1
            if target[v] == v:
                fixed = v
        if cntS == 0:
            continue                # this component does not affect the answer
        if fixed is not None:
            # component has a fixed point (a tree)
            if inS[fixed]:
                ans += cntS - 1
            else:
                ans += cntS
        else:
            # component has a cycle of length >= 2
            ans += cntS + 1

