import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    T = next(it)
    out_lines = []
    for _ in range(T):
        N = next(it)
        A = [next(it) for _ in range(N)]
        # positions for each value
        pos = [[] for _ in range(N + 1)]
        for i, v in enumerate(A, 1):
            pos[v].append(i)
        intervals = []
        for lst in pos:
            # pair consecutive occurrences
            for i in range(0, len(lst) - 1, 2):
                intervals.append((lst[i], lst[i + 1]))
        # sort by right endpoint (then left)
        intervals.sort(key=lambda x: (x[1], x[0]))
        # segment tree for range maximum on left endpoints
        size = 1
        while size < N:
            size <<= 1
        seg = [0] * (2 * size)
        def seg_update(p, val):
            i = p + size - 1
            if val > seg[i]:
                seg[i] = val
                i >>= 1
                while i:
                    newv = seg[i << 1]
                    if seg[i << 1 | 1] > newv:
                        newv = seg[i << 1 | 1]
                    seg[i] = newv
                    i >>= 1
        def seg_query(l, r):
            if l > r:
                return 0
            l += size - 1
            r += size - 1
            res = 0
            while l <= r:
                if l & 1:
                    if seg[l] > res:
                        res = seg[l]
                    l += 1
                if not (r & 1):
                    if seg[r] > res:
                        res = seg[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res
        # Fenwick tree for prefix maximum on right endpoints
        bit = [0] * (N + 1)
        def bit_update(i, val):
            while i <= N:
                if val > bit[i]:
                    bit[i] = val
                i += i & -i
        def bit_query(i):
            res = 0
            while i:
                if bit[i] > res:
                    res = bit[i]
                i -= i & -i
            return res
        # DP over intervals
        for l, r in intervals:
            best_inside = seg_query(l + 1, r - 1)
            best_before = bit_query(l - 1)
            cand = 1 + (best_inside if best_inside > best_before else best_before)
            # store result for future queries
            bit_update(r, cand)
            seg_update(l, cand)
        M = bit_query(N)  # maximum number of matched pairs
        ans = N - M
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

