from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        # If after removing any element we have fewer than k strings, answer is 0.
        if k > n - 1:
            return [0] * n

        # ---------- build trie ----------
        class Node:
            __slots__ = ('children', 'cnt', 'depth', 'words')
            def __init__(self, depth: int = 0):
                self.children = {}
                self.cnt = 0
                self.depth = depth
                self.words = []   # list of word indices that pass through this node

        nodes = [Node()]  # root node index 0, depth 0
        for idx, w in enumerate(words):
            node = 0
            # root contributes to all words
            nodes[node].cnt += 1
            for ch in w:
                child = nodes[node].children.get(ch)
                if child is None:
                    child = len(nodes)
                    nodes[node].children[ch] = child
                    nodes.append(Node(nodes[node].depth + 1))
                node = child
                nodes[node].cnt += 1
                nodes[node].words.append(idx)

        max_depth = max(node.depth for node in nodes)

        # ---------- compute for each depth how many nodes have count >= k ----------
        total_ge = [0] * (max_depth + 1)   # total_ge[d] = number of nodes at depth d with cnt >= k
        for node in nodes:
            if node.cnt >= k:
                total_ge[node.depth] += 1

        # ---------- find critical depths (unique node with count == k) ----------
        # blocked_depths[i] will contain the depths that become unavailable when word i is removed
        blocked_depths = [[] for _ in range(n)]
        for node in nodes:
            if node.cnt >= k and total_ge[node.depth] == 1 and node.cnt == k:
                d = node.depth
                for w_idx in node.words:
                    blocked_depths[w_idx].append(d)

        # ---------- segment tree for max depth with leaf value 1 ----------
        size = 1
        while size < max_depth + 1:
            size <<= 1
        seg = [0] * (2 * size)
        for d in range(max_depth + 1):
            if total_ge[d] > 0:
                seg[size + d] = 1
        for i in range(size - 1, 0, -1):
            seg[i] = seg[2 * i] | seg[2 * i + 1]

        def seg_update(pos: int, val: int) -> None:
            i = pos + size
            seg[i] = val
            i >>= 1
            while i:
                seg[i] = seg[2 * i] | seg[2 * i + 1]
                i >>= 1

        def seg_query_max() -> int:
            if seg[1] == 0:
                return -1
            i = 1
            while i < size:
                if seg[2 * i + 1]:
                    i = 2 * i + 1
                else:
                    i = 2 * i
            return i - size

        # ---------- answer each index ----------
        ans = [0] * n
        for i in range(n):
            # temporarily disable the depths that would be lost when word i is removed
            for d in blocked_depths[i]:
                seg_update(d, 0)
            best = seg_query_max()
            ans[i] = 0 if best == -1 else best
            # restore
            for d in blocked_depths[i]:
                seg_update(d, 1)
        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # forced[p] = character forced by a 'T' constraint, or None if free
        forced = [None] * L

        # Process 'T' constraints: they force characters
        for i, ch in enumerate(str1):
            if ch == 'T':
                for k, c in enumerate(str2):
                    p = i + k
                    if forced[p] is None:
                        forced[p] = c
                    elif forced[p] != c:
                        return ""

        # Data structures for analysing 'F' shifts
        # F[p] = set of characters that are forbidden at position p
        # (they would break a non‑dangerous shift that has p as its only good free position)
        F = [set() for _ in range(L)]

        # shifts_containing[p] = list of indices of dangerous shifts that have p as a candidate
        shifts_containing = [[] for _ in range(L)]

        dangerous_shifts = []  # each element: {'candidates': [...], 'max': int, 'idx': int}

        # Examine each 'F' shift
        for i, ch in enumerate(str1):
            if ch != 'F':
                continue

            good_positions = []   # (position, required char) for free positions with str2 != 'a'
            candidates = []       # free positions where str2 == 'a'
            forced_mismatch = False

            for k in range(m):
                p = i + k
                c = str2[k]
                if forced[p] is not None:
                    if forced[p] != c:
                        forced_mismatch = True
                        break
                else:
                    if c != 'a':
                        good_positions.append((p, c))
                    else:
                        candidates.append(p)

            if forced_mismatch:
                # shift already satisfied by a forced mismatch – no restrictions
                continue

            if good_positions:
                # shift satisfied because of a good free position
                if len(good_positions) == 1:
                    p, c = good_positions[0]
                    F[p].add(c)
                continue

            # No good free position → the shift is dangerous
            if not candidates:
                return ""  # all positions are forced and match str2 → impossible

            idx = len(dangerous_shifts)
            max_c = max(candidates)
            dangerous_shifts.append({
                'candidates': candidates,
                'max': max_c,
                'idx': idx
            })
            for p in candidates:
                shifts_containing[p].append(idx)

        # If there are no dangerous shifts, the answer is just forced chars + 'a's
        if not dangerous_shifts:
            res = []
            for p in range(L):
                if forced[p] is not None:
                    res.append(forced[p])
                else:
                    res.append('a')
            return ''.join(res)

        # For each free position, determine the smallest character > 'a' that is not forbidden
        min_char = [None] * L
        for p in range(L):
            if forced[p] is not None:
                continue
            forbidden = F[p]
            for code in range(ord('b'), ord('z') + 1):
                ch = chr(code)
                if ch not in forbidden:
                    min_char[p] = ch
                    break
            # if no character found, min_char[p] stays None (position unusable)

        # Process dangerous shifts in increasing order of their rightmost candidate
        dangerous_shifts.sort(key=lambda x: x['max'])
        covered = [False] * len(dangerous_shifts)

        # Build initial result with forced chars and 'a's
        result = [None] * L
        for p in range(L):
            if forced[p] is not None:
                result[p] = forced[p]
            else:
                result[p] = 'a'

        # Greedily select a usable position for each uncovered dangerous shift
        for shift in dangerous_shifts:
            idx = shift['idx']
            if covered[idx]:
                continue

            # Find the rightmost usable position among the candidates
            cands = shift['candidates']
            # iterate from right to left
            usable = None
            for p in sorted(cands, reverse=True):
                if min_char[p] is not None:
                    usable = p
                    break
            if usable is None:
                return ""  # no character can be placed without breaking another constraint

            # Assign the chosen character
            result[usable] = min_char[usable]

            # Mark all dangerous shifts that contain this position as covered
            for sidx in shifts_containing[usable]:
                covered[sidx] = True

        return ''.join(result)

