class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Compute perimeter length
        C = 4 * side

        # Compute arc length s for each point (clockwise from (0,0))
        s_list = []
        for x, y in points:
            if y == 0:
                s = x
            elif x == side:
                s = side + y
            elif y == side:
                s = 2 * side + (side - x)
            else:  # x == 0
                s = 3 * side + (side - y)
            s_list.append(s)

        s_list.sort()
        n = len(s_list)

        # Duplicate with +C to handle circular wrap-around
        s_dup = s_list + [s + C for s in s_list]

        # Helper function to check feasibility for a given D
        def feasible(D: int) -> bool:
            # Compute nxt[i] = first index j > i with s_dup[j] >= s_dup[i] + D
            size = 2 * n
            nxt = [size] * size
            j = 0
            for i in range(size):
                if j < i + 1:
                    j = i + 1
                target = s_dup[i] + D
                while j < size and s_dup[j] < target:
                    j += 1
                nxt[i] = j

            # Try each possible starting point in the original circle
            for i in range(n):
                idx = i
                # Apply nxt (k-1) times to get the k-th point in greedy order
                for _ in range(k - 1):
                    if idx >= size:
                        break
                    idx = nxt[idx]
                if idx < size and s_dup[idx] <= s_dup[i] + C - D:
                    return True
            return False

        # Binary search the answer
        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

