def solve() -> None:
    import sys
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    if N == 1:
        print(-1)
        return

    NEG = -10 ** 9

    # ---------- root the tree, get parent / children ----------
    root = 1
    parent = [0] * (N + 1)
    children = [[] for _ in range(N + 1)]
    order = []                     # postorder
    stack = [(root, 0)]
    parent[root] = -1
    while stack:
        v, state = stack.pop()
        if state == 0:
            stack.append((v, 1))
            for to in adj[v]:
                if to != parent[v]:
                    parent[to] = v
                    children[v].append(to)
                    stack.append((to, 0))
        else:
            order.append(v)

    # ---------- down[v] : F(parent(v), v) ----------
    down = [NEG] * (N + 1)
    for v in order:                # postorder, children already processed
        if len(children[v]) >= 3:
            vals = []
            for c in children[v]:
                vals.append(down[c] if down[c] != NEG else 1)
            # three largest values
            # simple selection because degree can be large, but total O(N)
            vals.sort(reverse=True)
            down[v] = 1 + vals[0] + vals[1] + vals[2]
        else:
            down[v] = NEG

    # ---------- up[v] : F(parent(v), v) from the parent side ----------
    up = [NEG] * (N + 1)
    up[root] = NEG                 # no parent side
    stack = [root]
    while stack:
        u = stack.pop()
        # build contributions of all neighbours of u
        contribs = []
        for c in children[u]:
            val = down[c] if down[c] != NEG else 1
            contribs.append((val, c))
        if parent[u] != -1:
            val = up[u] if up[u] != NEG else 1
            contribs.append((val, parent[u]))

        # keep the four largest contributions
        best = []   # list of (value, neighbour)
        for val, nb in contribs:
            if len(best) < 4:
                best.append((val, nb))
            else:
                # find smallest in best
                min_idx = 0
                min_val = best[0][0]
                for i in range(1, 4):
                    if best[i][0] < min_val:
                        min_val = best[i][0]
                        min_idx = i
                if val > min_val:
                    best[min_idx] = (val, nb)
        best.sort(key=lambda x: x[0], reverse=True)
        # best[0] .. best[3] (some may be missing)
        best_vals = [x[0] for x in best]
        best_nbs = [x[1] for x in best]

        # compute up for every child of u
        for c in children[u]:
            if len(adj[c]) < 4 or len(contribs) < 4:
                up[c] = NEG
                continue

            # need the three largest contributions among neighbours of u
            # except the neighbour c itself
            if c == best_nbs[0]:
                # use best[1], best[2] and best[3]
                if len(best_vals) >= 4:
                    sum_excl = best_vals[1] + best_vals[2] + best_vals[3]
                else:
                    up[c] = NEG
                    continue
            elif c == best_nbs[1]:
                if len(best_vals) >= 4:
                    sum_excl = best_vals[0] + best_vals[2] + best_vals[3]
                else:
                    up[c] = NEG
                    continue
            elif c == best_nbs[2]:
                if len(best_vals) >= 4:
                    sum_excl = best_vals[0] + best_vals[1] + best_vals[3]
                else:
                    up[c] = NEG
                    continue
            else:
                # c not among the three largest
                if len(best_vals) >= 3:
                    sum_excl = best_vals[0] + best_vals[1] + best_vals[2]
                else:
                    up[c] = NEG
                    continue

            up[c] = 1 + sum_excl

        # continue DFS to children
        for c in children[u]:
            stack.append(c)

    # ---------- evaluate candidates ----------
    ans = -1
    for v in range(1, N + 1):
        # internal vertex without a parent (needs 4 children)
        if len(children[v]) >= 4:
            cw = []
            for c in children[v]:
                cw.append(down[c] if down[c] != NEG else 1)
            cw.sort(reverse=True)
            cand = 1 + cw[0] + cw[1] + cw[2] + cw[3]
            if cand > ans:
                ans = cand

        # internal vertex with a leaf parent (needs total degree >= 4)
        if len(adj[v]) >= 4:
            nw = []
            for c in children[v]:
                nw.append(down[c] if down[c] != NEG else 1)
            if parent[v] != -1:
                nw.append(up[v] if up[v] != NEG else 1)
            nw.sort(reverse=True)
            cand = 2 + nw[0] + nw[1] + nw[2]
            if cand > ans:
                ans = cand

    print(ans)

if __name__ == "__main__":
    solve()

