class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # directions: 0: down-right (1,1), 1: down-left (1,-1), 2: up-left (-1,-1), 3: up-right (-1,1)
        dx = [1, 1, -1, -1]
        dy = [1, -1, -1, 1]

        # dp_end[d][i][j] = max length of a segment ending at (i,j) moving in direction d, starting with 1
        dp_end = [[[0] * m for _ in range(n)] for _ in range(4)]
        # start1, start2, start0: DP for segments starting at (i,j) with first value 1,2,0 respectively
        start1 = [[[0] * m for _ in range(n)] for _ in range(4)]
        start2 = [[[0] * m for _ in range(n)] for _ in range(4)]
        start0 = [[[0] * m for _ in range(n)] for _ in range(4)]

        # Compute dp_end (forward DP)
        for d in range(4):
            # iterate in order such that previous cell in direction d is processed first
            if dx[d] == 1:
                i_iter = range(n)
            else:
                i_iter = range(n-1, -1, -1)
            if dy[d] == 1:
                j_iter = range(m)
            else:
                j_iter = range(m-1, -1, -1)
            for i in i_iter:
                row = dp_end[d][i]
                for j in j_iter:
                    val = grid[i][j]
                    best = 1 if val == 1 else 0
                    pi = i - dx[d]
                    pj = j - dy[d]
                    if 0 <= pi < n and 0 <= pj < m:
                        prev_len = dp_end[d][pi][pj]
                        if prev_len:
                            # expected value for the next step (length prev_len)
                            exp = 2 if (prev_len & 1) else 0
                            if val == exp:
                                cand = prev_len + 1
                                if cand > best:
                                    best = cand
                    row[j] = best

        # Compute start DP (reverse direction order)
        for d in range(4):
            # iterate from far end to start so that the next cell in direction d is already processed
            if dx[d] == 1:
                i_iter = range(n-1, -1, -1)
            else:
                i_iter = range(n)
            if dy[d] == 1:
                j_iter = range(m-1, -1, -1)
            else:
                j_iter = range(m)
            for i in i_iter:
                row1 = start1[d][i]
                row2 = start2[d][i]
                row0 = start0[d][i]
                for j in j_iter:
                    val = grid[i][j]
                    # start with 1 -> next expected is 2
                    if val == 1:
                        ni = i + dx[d]
                        nj = j + dy[d]
                        if 0 <= ni < n and 0 <= nj < m:
                            nxt = start2[d][ni][nj]
                            if nxt:
                                row1[j] = nxt + 1
                            else:
                                row1[j] = 1
                        else:
                            row1[j] = 1
                    else:
                        row1[j] = 0
                    # start with 2 -> next expected is 0
                    if val == 2:
                        ni = i + dx[d]
                        nj = j + dy[d]
                        if 0 <= ni < n and 0 <= nj < m:
                            nxt = start0[d][ni][nj]
                            if nxt:
                                row2[j] = nxt + 1
                            else:
                                row2[j] = 1
                        else:
                            row2[j] = 1
                    else:
                        row2[j] = 0
                    # start with 0 -> next expected is 2
                    if val == 0:
                        ni = i + dx[d]
                        nj = j + dy[d]
                        if 0 <= ni < n and 0 <= nj < m:
                            nxt = start2[d][ni][nj]
                            if nxt:
                                row0[j] = nxt + 1
                            else:
                                row0[j] = 1
                        else:
                            row0[j] = 1
                    else:
                        row0[j] = 0

        # Evaluate all possible V-shaped segments
        ans = 0
        for i in range(n):
            for j in range(m):
                val = grid[i][j]
                for d in range(4):
                    seg_len = dp_end[d][i][j]
                    if seg_len > ans:
                        ans = seg_len
                    if seg_len:
                        d2 = (d + 1) & 3  # clockwise turn
                        if val == 1:
                            second_len = start1[d2][i][j]
                        elif val == 2:
                            second_len = start2[d2][i][j]
                        else:  # val == 0
                            second_len = start0[d2][i][j]
                        if second_len:
                            total = seg_len + second_len - 1
                            if total > ans:
                                ans = total
        return ans

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:1+N]))
    o = sum(1 for x in A if x % 2 == 0)
    n = N
    mod4 = n % 4
    if n % 2 == 0:
        if mod4 == 0:
            win = (o % 2 == 1)
        else:
            win = False
    else:
        if mod4 == 1:
            win = (o % 2 == 0) or (o == n)
        else:  # mod4 == 3
            win = (o != n)
    print("Fennec" if win else "Snuke")

if __name__ == "__main__":
