class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""
        s = [ord(ch) - ord('a') for ch in caption]
        INF = 10**18

        # prefix sums of costs for each letter
        P = [[0] * (n + 1) for _ in range(26)]
        for i in range(n):
            o = s[i]
            for c in range(26):
                P[c][i + 1] = P[c][i] + abs(o - c)

        # forward DP: minimal cost to convert prefix of length i
        dp = [INF] * (n + 1)
        dp[0] = 0
        # best_c = min_{l <= i} (dp[l] - P_c[l])
        best = [-P[c][0] for c in range(26)]
        for i in range(1, n + 1):
            if i < 3:
                dp[i] = INF
            else:
                mn = INF
                for c in range(26):
                    val = P[c][i] + best[c]
                    if val < mn:
                        mn = val
                dp[i] = mn
            if dp[i] < INF:
                for c in range(26):
                    val = dp[i] - P[c][i]
                    if val < best[c]:
                        best[c] = val

        # backward DP: minimal cost to convert suffix starting at i
        dp2 = [INF] * (n + 1)
        dp2[n] = 0
        # best_future_c = min_{t >= i} (dp2[t] + P_c[t])
        best_future = [P[c][n] for c in range(26)]
        for i in range(n - 1, -1, -1):
            if i + 3 > n:
                dp2[i] = INF
            else:
                mn = INF
                for c in range(26):
                    val = -P[c][i] + best_future[c]
                    if val < mn:
                        mn = val
                dp2[i] = mn
            if dp2[i] < INF:
                for c in range(26):
                    val = dp2[i] + P[c][i]
                    if val < best_future[c]:
                        best_future[c] = val

        if dp[n] >= INF:
            return ""

        # suffix best representation
        # char[i] = first character of optimal suffix from i (or -1 if empty)
        # length[i] = length of first block
        # next_idx[i] = index after the first block (i + length[i])
        char = [-1] * (n + 1)
        length = [0] * (n + 1)
        next_idx = [n] * (n + 1)
        # for i = n: empty suffix
        char[n] = -1
        length[n] = 0
        next_idx[n] = n

        # helper to compare two suffix strings starting at p1 and p2
        def suffix_cmp(p1, p2):
            while p1 != n and p2 != n:
                c1 = char[p1]
                c2 = char[p2]
                if c1 != c2:
                    return -1 if c1 < c2 else 1
                l1 = length[p1]
                l2 = length[p2]
                if l1 != l2:
                    return -1 if l1 < l2 else 1
                p1 += l1
                p2 += l2
            if p1 == n and p2 == n:
                return 0
            return -1 if p1 == n else 1

        # compare candidates (c, t1) and (c, t2) for start position i
        def candidate_less(i, c, t1, t2):
            L1 = t1 - i
            L2 = t2 - i
            rem1 = L1
            rem2 = L2
            p1 = t1
            p2 = t2
            while True:
                if rem1 > 0 and rem2 > 0:
                    rem1 -= 1
                    rem2 -= 1
                    continue
                if rem1 == 0 and rem2 == 0:
                    res = suffix_cmp(p1, p2)
                    if res < 0:
                        return True
                    return False
                if rem1 == 0:
                    # S1 at suffix p1, S2 still has c
                    if p1 == n:
                        return True
                    d = char[p1]
                    if d < c:
                        return True
                    if d > c:
                        return False
                    # d == c
                    p1 += length[p1]
                    rem2 -= 1
                    continue
                # rem2 == 0
                if p2 == n:
                    return False
                d = char[p2]
                if d < c:
                    return False
                if d > c:
                    return True
                p2 += length[p2]
                rem1 -= 1

        # for each letter c, maintain best t for each R value (P_c[t] + dp2[t])
        best_by_R = [{} for _ in range(26)]

        # process i from n-1 down to 0
        for i in range(n - 1, -1, -1):
            # answer for position i
            if dp2[i] < INF:
                found_c = -1
                found_t = -1
                for c in range(26):
                    v = P[c][i] + dp2[i]
                    if v in best_by_R[c]:
                        found_c = c
                        found_t = best_by_R[c][v]
                        break  # smallest c
                if found_c != -1:
                    char[i] = found_c
                    length[i] = found_t - i
                    next_idx[i] = found_t

            # add new candidate t = (i-1)+3 = i+2 for the next iteration (i-1)
            if i >= 1:
                t_new = i + 2
                if t_new <= n and dp2[t_new] < INF:
                    i_next = i - 1
                    for c in range(26):
                        v_new = P[c][t_new] + dp2[t_new]
                        if v_new in best_by_R[c]:
                            t_best = best_by_R[c][v_new]
                            if candidate_less(i_next, c, t_new, t_best):
                                best_by_R[c][v_new] = t_new
                        else:
                            best_by_R[c][v_new] = t_new

        # reconstruct answer from position 0
        if char[0] == -1:
            return ""
        res = []
        i = 0
        while i < n:
            c = char[i]
            L = length[i]
            res.append(chr(ord('a') + c) * L)
            i = next_idx[i]
        return "".join(res)

