def solve():
    import sys
    input = sys.stdin.readline

    # generate primes up to 100000 (enough for sqrt(1e9) = 31623)
    LIMIT = 100000
    is_prime = [True] * (LIMIT + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(LIMIT**0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            is_prime[start:LIMIT+1:step] = [False] * ((LIMIT - start)//step + 1)
    primes = [i for i, v in enumerate(is_prime) if v]

    def factorize(n):
        """return list of (prime, exponent) for n <= 1e9"""
        res = []
        for p in primes:
            if p * p > n:
                break
            if n % p == 0:
                cnt = 0
                while n % p == 0:
                    n //= p
                    cnt += 1
                res.append((p, cnt))
        if n > 1:
            res.append((n, 1))
        return res

    def primitive_root_prime_power(p, e):
        """return (a, m) where m = p^{e+1} and a has order p^e modulo m"""
        m = pow(p, e + 1)
        phi = m // p * (p - 1)  # p^e * (p-1)
        # factor p-1
        temp = p - 1
        prime_factors = set()
        for pr in primes:
            if pr * pr > temp:
                break
            if temp % pr == 0:
                prime_factors.add(pr)
                while temp % pr == 0:
                    temp //= pr
        if temp > 1:
            prime_factors.add(temp)
        prime_factors.add(p)
        # find primitive root g
        g = 2
        while True:
            ok = True
            for q in prime_factors:
                if pow(g, phi // q, m) == 1:
                    ok = False
                    break
            if ok:
                break
            g += 1
        a = pow(g, p - 1, m)
        return a, m

    out = []
    T = int(input())
    for _ in range(T):
        line = input()
        while line.strip() == '':
            line = input()
        N = int(line)
        if N == 1:
            out.append("1 1")
            continue

        factors = factorize(N)
        pairs = []
        for p, e in factors:
            if p == 2:
                m = 1 << (e + 2)  # 2^{e+2}
                a = 5
                pairs.append((a, m))
            else:
                a, m = primitive_root_prime_power(p, e)
                pairs.append((a, m))

        # combine via CRT
        a, m = pairs[0]
        for a2, m2 in pairs[1:]:
            inv = pow(m, -1, m2)  # m and m2 are coprime
            t = (a2 - a) * inv % m2
            a = a + m * t
            m = m * m2
            a %= m
        out.append(f"{a} {m}")

    sys.stdout.write("\n".join(out))

