import sys

def solve() -> None:
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    N = int(next(it))
    intervals = [(int(next(it)), int(next(it))) for _ in range(N)]
    Q = int(next(it))
    queries = [int(next(it)) for _ in range(Q)]

    if not queries:
        return
    maxX = max(queries)
    n = maxX                       # number of tokens (initial ratings 1..n)
    size = 1 << (n.bit_length())   # size of segment tree (power of two)

    INF = 10 ** 9
    minv = [0] * (2 * size)
    maxv = [0] * (2 * size)
    lazy = [0] * (2 * size)

    # initialise leaves
    for i in range(size):
        if i < n:
            v = i + 1
            minv[size + i] = v
            maxv[size + i] = v
        else:
            minv[size + i] = INF
            maxv[size + i] = -INF

    for i in range(size - 1, 0, -1):
        minv[i] = min(minv[2 * i], minv[2 * i + 1])
        maxv[i] = max(maxv[2 * i], maxv[2 * i + 1])

    def apply(node: int, val: int) -> None:
        minv[node] += val
        maxv[node] += val
        lazy[node] += val

    def push(node: int) -> None:
        if lazy[node]:
            v = lazy[node]
            apply(node * 2, v)
            apply(node * 2 + 1, v)
            lazy[node] = 0

    # range add on [l, r] (1-indexed)
    def range_add(l: int, r: int, val: int, node: int, nl: int, nr: int) -> None:
        if r < nl or nr < l:
            return
        if l <= nl and nr <= r:
            apply(node, val)
            return
        push(node)
        mid = (nl + nr) // 2
        range_add(l, r, val, node * 2, nl, mid)
        range_add(l, r, val, node * 2 + 1, mid + 1, nr)
        minv[node] = min(minv[node * 2], minv[node * 2 + 1])
        maxv[node] = max(maxv[node * 2], maxv[node * 2 + 1])

    # find leftmost index with value >= L
    def find_first_ge(L: int, node: int, nl: int, nr: int) -> int:
        if maxv[node] < L:
            return n + 1
        if nl == nr:
            return nl
        push(node)
        mid = (nl + nr) // 2
        if maxv[node * 2] >= L:
            return find_first_ge(L, node * 2, nl, mid)
        else:
            return find_first_ge(L, node * 2 + 1, mid + 1, nr)

    # find rightmost index with value <= R
    def find_last_le(R: int, node: int, nl: int, nr: int) -> int:
        if minv[node] > R:
            return 0
        if nl == nr:
            return nl
        push(node)
        mid = (nl + nr) // 2
        if minv[node * 2 + 1] <= R:
            return find_last_le(R, node * 2 + 1, mid + 1, nr)
        else:
            return find_last_le(R, node * 2, nl, mid)

    # point query
    def point_query(pos: int, node: int, nl: int, nr: int) -> int:
        if nl == nr:
            return minv[node]
        push(node)
        mid = (nl + nr) // 2
        if pos <= mid:
            return point_query(pos, node * 2, nl, mid)
        else:
            return point_query(pos, node * 2 + 1, mid + 1, nr)

    # process all contests
    for L, R in intervals:
        lo = find_first_ge(L, 1, 1, size)
        if lo > n:
            continue
        hi = find_last_le(R, 1, 1, size)
        if hi == 0 or lo > hi:
            continue
        range_add(lo, hi, 1, 1, 1, size)

    out = []
    for X in queries:
        out.append(str(point_query(X, 1, 1, size)))
    sys.stdout.write("\n".join(out))

