import sys

def mat_mult(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity matrix
    res = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = mat
    while exp:
        if exp & 1:
            res = mat_mult(res, base, mod)
        base = mat_mult(base, base, mod)
        exp >>= 1
    return res

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = [[int(next(it)) for _ in range(N)] for _ in range(N)]

    # count zeros
    K = sum(1 for i in range(N) for j in range(N) if A[i][j] == 0)

    if p == 2:
        # all entries become 1
        B = [[1] * N for _ in range(N)]
        S = mat_pow(B, 2, 2)
    elif p == 3:
        sign = 1 if (K % 2 == 0) else 2  # (-1)^K mod 3
        A3 = mat_pow(A, 3, 3)

        # contributions from diagonal zeros
        R = [[0] * N for _ in range(N)]
        C = [[0] * N for _ in range(N)]
        O = [[0] * N for _ in range(N)]

        diag_zero = [i for i in range(N) if A[i][i] == 0]
        for i in diag_zero:
            for j in range(N):
                R[i][j] = A[i][j] % 3
        for j in diag_zero:
            for i in range(N):
                C[i][j] = A[i][j] % 3

        for i in range(N):
            for j in range(N):
                if i != j and A[i][j] == 0:
                    O[i][j] = A[j][i] % 3

        S = [[0] * N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                val = (A3[i][j] + R[i][j] + C[i][j] + O[i][j]) % 3
                S[i][j] = (sign * val) % 3
    else:
        # p >= 5
        sign = 1 if (K % 2 == 0) else (p - 1)  # (-1)^K mod p
        Ap = mat_pow(A, p, p)
        S = [[(sign * Ap[i][j]) % p for j in range(N)] for i in range(N)]

    out_lines = [' '.join(map(str, row)) for row in S]
    sys.stdout.write('\n'.join(out_lines))

