class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        bits = [1 if ch == '1' else 0 for ch in s]
        INF = 10 ** 9

        # check whether we can force every run of identical characters
        # to have length at most L using at most numOps flips
        def feasible(L: int) -> bool:
            # dp0[len] = minimal flips for processed prefix,
            # ending with bit 0 and current run length = len (1..L)
            dp0 = [INF] * (L + 2)
            dp1 = [INF] * (L + 2)

            # first character
            if bits[0] == 0:
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            for i in range(1, n):
                si = bits[i]
                ndp0 = [INF] * (L + 2)
                ndp1 = [INF] * (L + 2)

                for prev_bit in (0, 1):
                    prev_dp = dp0 if prev_bit == 0 else dp1
                    for prev_len in range(1, L + 1):
                        cur_val = prev_dp[prev_len]
                        if cur_val == INF:
                            continue

                        # keep the same bit -> extend the run
                        new_len = prev_len + 1
                        if new_len <= L:
                            cost = cur_val + (prev_bit != si)
                            if prev_bit == 0:
                                if cost < ndp0[new_len]:
                                    ndp0[new_len] = cost
                            else:
                                if cost < ndp1[new_len]:
                                    ndp1[new_len] = cost

                        # switch to the other bit -> start a new run of length 1
                        other = 1 - prev_bit
                        cost = cur_val + (other != si)
                        if other == 0:
                            if cost < ndp0[1]:
                                ndp0[1] = cost
                        else:
                            if cost < ndp1[1]:
                                ndp1[1] = cost

                dp0, dp1 = ndp0, ndp1

            best = min(min(dp0[1:]), min(dp1[1:]))
            return best <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

