# segment tree for D :  max query, need rightmost index >= X
class SegTreeMax:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.inf = -10**30
        self.t = [self.inf] * (2 * self.size)
        # build leaves
        for i, v in enumerate(data):
            self.t[self.size + i] = v
        # build inner nodes
        for i in range(self.size - 1, 0, -1):
            self.t[i] = max(self.t[i << 1], self.t[i << 1 | 1])

    # find rightmost index in [l, r] (inclusive) with value >= X
    # return 0 if not found  (0 is outside the real range)
    def rightmost_ge(self, l, r, X):
        if l > r:
            return 0
        return self._rightmost_ge(1, 0, self.size - 1, l, r, X)

    def _rightmost_ge(self, node, nl, nr, ql, qr, X):
        if nr < ql or nl > qr or self.t[node] < X:
            return 0
        if nl == nr:
            return nl
        mid = (nl + nr) // 2
        # search right child first
        res = self._rightmost_ge(node << 1 | 1, mid + 1, nr, ql, qr, X)
        if res:
            return res
        return self._rightmost_ge(node << 1, nl, mid, ql, qr, X)


# segment tree for G :  min query, need leftmost index <= Y
class SegTreeMin:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.inf = 10**30
        self.t = [self.inf] * (2 * self.size)
        for i, v in enumerate(data):
            self.t[self.size + i] = v
        for i in range(self.size - 1, 0, -1):
            self.t[i] = min(self.t[i << 1], self.t[i << 1 | 1])

    # find leftmost index in [l, r] with value <= Y
    # return n+1 (i.e. N+1) if not found
    def leftmost_le(self, l, r, Y):
        if l > r:
            return self.n + 1
        return self._leftmost_le(1, 0, self.size - 1, l, r, Y)

    def _leftmost_le(self, node, nl, nr, ql, qr, Y):
        if nr < ql or nl > qr or self.t[node] > Y:
            return self.n + 1
        if nl == nr:
            return nl
        mid = (nl + nr) // 2
        # search left child first
        res = self._leftmost_le(node << 1, nl, mid, ql, qr, Y)
        if res != self.n + 1:
            return res
        return self._leftmost_le(node << 1 | 1, mid + 1, nr, ql, qr, Y)


