def solve() -> None:
    it = iter(sys.stdin.read().split())
    N = int(next(it))
    A = [0] * (N + 1)          # 1‑based
    for i in range(1, N + 1):
        A[i] = int(next(it))

    # prefix sums
    P = [0] * (N + 1)
    for i in range(1, N + 1):
        P[i] = P[i - 1] + A[i]

    # D[i] = P[i] + A[i]   (1‑based)
    D = [0] * (N + 1)
    for i in range(1, N + 1):
        D[i] = P[i] + A[i]

    # G[i] = P[i-1] - A[i]   (1‑based)
    G = [0] * (N + 1)
    for i in range(1, N + 1):
        G[i] = P[i - 1] - A[i]

    # segment trees, use 0‑based indexing inside the trees
    # dummy element at index 0 will be ignored (set to -inf / +inf)
    D_data = [-10**30] + D[1:]               # length N+1, index 0 is dummy
    G_data = [10**30] + G[1:]                # length N+1

    segD = SegTreeMax(D_data)
    segG = SegTreeMin(G_data)

    ans = [0] * (N + 1)

    for K in range(1, N + 1):
        l = r = K
        while True:
            changed = False

            # ----- try to expand to the right -----
            # find leftmost j > K with G[j] <= P[l-1]
            j = segG.leftmost_le(K + 1, N, P[l - 1])
            new_r = N if j == N + 1 else j - 1
            if new_r > r:
                r = new_r
                changed = True

            # ----- try to expand to the left -----
            # find rightmost i < K with D[i] >= P[r]
            i = segD.rightmost_ge(1, K - 1, P[r])
            new_l = 1 if i == 0 else i + 1
            if new_l < l:
                l = new_l
                changed = True

            if not changed:
                break

        ans[K] = P[r] - P[l - 1]

    print(' '.join(str(ans[i]) for i in range(1, N + 1)))


