from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Numbers larger than threshold cannot have any edge (lcm >= max(a,b) > threshold).
        # So each of them forms its own connected component.
        isolated_gt = 0
        val_to_idx = {}          # maps each value <= threshold to a DSU index
        for v in nums:
            if v > threshold:
                isolated_gt += 1
            else:
                if v not in val_to_idx:          # values are unique, but keep check for safety
                    val_to_idx[v] = len(val_to_idx)

        k = len(val_to_idx)      # number of nodes with value <= threshold
        if k == 0:
            return isolated_gt

        # DSU structure for the nodes with value <= threshold
        parent = list(range(k))
        rank = [0] * k

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            xr = find(x)
            yr = find(y)
            if xr == yr:
                return
            if rank[xr] < rank[yr]:
                parent[xr] = yr
            elif rank[xr] > rank[yr]:
                parent[yr] = xr
            else:
                parent[yr] = xr
                rank[xr] += 1

        # For each multiple m (1 .. threshold) we keep the first divisor encountered.
        # If another divisor of m appears later, we union it with the stored one.
        first_div = [-1] * (threshold + 1)   # first_div[m] = DSU index of first divisor of m

        for val, idx in val_to_idx.items():
            # iterate over all multiples of val not exceeding threshold
            for m in range(val, threshold + 1, val):
                if first_div[m] == -1:
                    first_div[m] = idx
                else:
                    union(idx, first_div[m])

        # count distinct DSU roots among the <= threshold numbers
        roots = set()
        for i in range(k):
            roots.add(find(i))

        return isolated_gt + len(roots)
